from PIL import Image
import numpy as np
from scipy import ndimage
cam_specs={
'left':np.array([[.7326154777847623,.13381387467676192,-.6673592800390178,-.775],[-.6806427563048065,.1440316742115515,-.718317697898091,-.856],[0,.9804839232582088,.1965992783104522,1.209],[0,0,0,1]]),
'right':np.array([[.7326154777847623,-.13381387467676192,.6673592800390178,.775],[.6806427563048065,.1440316742115515,-.718317697898091,-.856],[0,.9804839232582088,.1965992783104522,1.209],[0,0,0,1]])}
for cam,T in cam_specs.items():
 im=np.asarray(Image.open(f'/app/output/initial/last/{cam}.jpg')); d=np.load(f'/app/output/initial/depth_{cam}.npy')[0].astype(float)
 def xyz(x,y):
  x=np.array(x); y=np.array(y); z=d[y,x]; gl=np.array([(x-160)*z/386.2741699796952,-(y-160)*z/386.2741699796952,-z]); return (T[:3,:3]@gl + T[:3,3,None]).T
 print('\n',cam)
 # likely flower head manually pixels
 for name,coords in {'pink_head':[(200,185),(198,190),(195,195),(205,190)], 'stem':[(210,198),(220,200),(230,205),(240,205),(250,210)], 'vase rim':[(170,147),(180,150),(190,150)]}.items():
  print(name)
  for x,y in coords:
   if x<320: print((x,y),im[y,x].tolist(),round(d[y,x],3),np.round(xyz([x],[y])[0],3))
 # local connected rose pixels threshold
 m=(im[:,:,0]>110)&(im[:,:,2]>60)&(im[:,:,0]>im[:,:,1]*1.3)&(im[:,:,2]>im[:,:,1]*1.05)
 lab,n=ndimage.label(m)
 objs=[]
 for i in range(1,n+1):
  yy,xx=np.where(lab==i)
  if len(xx)>20:
   p=xyz(xx,yy)
   objs.append((len(xx),tuple(np.round(np.median(p,axis=0),3)),(int(xx.min()),int(yy.min()),int(xx.max()),int(yy.max()))))
 print('pink comps',sorted(objs,reverse=True)[:8])
